AiOverlayToolsAsyncWaiter::AiOverlayToolsAsyncWaiter(
    AiOverlayTools* proxy) : proxy_(proxy) {}

AiOverlayToolsAsyncWaiter::~AiOverlayToolsAsyncWaiter() = default;





void AiOverlayToolRegistryInterceptorForTesting::GetToolDefinitions(GetToolDefinitionsCallback callback) {
  GetForwardingInterface()->GetToolDefinitions(std::move(callback));
}
AiOverlayToolRegistryAsyncWaiter::AiOverlayToolRegistryAsyncWaiter(
    AiOverlayToolRegistry* proxy) : proxy_(proxy) {}

AiOverlayToolRegistryAsyncWaiter::~AiOverlayToolRegistryAsyncWaiter() = default;


void AiOverlayToolRegistryAsyncWaiter::GetToolDefinitions(
    std::string* out_json_definitions) {
  base::RunLoop loop;
  proxy_->GetToolDefinitions(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::string* out_json_definitions
,
             const std::string& json_definitions) {*out_json_definitions = std::move(json_definitions);
            loop->Quit();
          },
          &loop,
          out_json_definitions));
  loop.Run();
}

std::string AiOverlayToolRegistryAsyncWaiter::GetToolDefinitions(
    ) {
  std::string async_wait_result;
  GetToolDefinitions(&async_wait_result);
  return async_wait_result;
}






